import { notificationsFor, unreadNotifications } from './notifications-v40.js';
const names={letter:'Letter',gift:'Gift',health:'Health'};
function letterDate(s,n,ui){
 const m=s.conversations?.threads?.[n.personId]?.find(m=>m.id===n.sourceId),gap=s.day-n.day;
 return `Letter from ${ui.date(n.day)}${Number.isInteger(m?.age)?' · Age '+m.age:''}${gap>0?' · '+(gap>=365?Math.floor(gap/365)+' year'+(gap>=730?'s':''):gap+' day'+(gap===1?'':'s'))+' ago':''}`;
}
export function renderInbox(s,ui,{selectedId,soundEnabled=true,page=0}={}){
  const {e,button,date,paragraphs}=ui,rows=notificationsFor(s),unread=unreadNotifications(s),pages=Math.max(1,Math.ceil(rows.length/20)),current=Math.max(0,Math.min(pages-1,Number.isSafeInteger(page)?page:0)),shown=rows.slice(current*20,(current+1)*20),retention=s.inbox?.retention;
  const paging=pages>1?`<nav class="inbox-paging" aria-label="Inbox pages">${button('Previous','inbox-page',String(current-1),'ghost small',current===0)}<span>Page ${current+1} of ${pages} · ${rows.length} kept</span>${button('Next','inbox-page',String(current+1),'ghost small',current===pages-1)}</nav>`:'';
  return `<header class="inbox-heading"><span class="eyebrow">LETTERS &amp; NOTICES</span><h2 id="inbox-title" tabindex="-1">Your Inbox</h2><p>${unread?unread+' Unread':'All Caught Up'}</p><div class="inbox-tools">${unread?button('Mark All Read','notice-read-all','','ghost small'):''}${button('Sound '+(soundEnabled?'On':'Off'),'notification-sound','','ghost small',false,soundEnabled)}</div></header>${paging}${retention?`<p class="inbox-retention" role="status">Earlier retention record: ${retention.olderUnread} unread and ${retention.olderRead} read notices are outside the 400-notice archive. Letter threads and original game records remain separately available; older notice text is no longer retained here.</p>`:''}<div class="inbox-list">${shown.map(n=>`<article class="inbox-entry ${n.read?'read':'unread'} ${n.id===selectedId?'open':''}"><button type="button" class="inbox-entry-open" data-op="notice-open" data-id="${e(n.id)}" aria-expanded="${n.id===selectedId}"><span class="inbox-unread-dot" aria-label="${n.read?'Read':'Unread'}"></span><span><small>${names[n.kind]} · ${e(date(n.day))}</small><strong>${e(n.title)}</strong></span><span aria-hidden="true">${n.id===selectedId?'−':'+'}</span></button>${n.id===selectedId?`<div class="inbox-letter">${n.kind==='letter'?`<p class="inbox-letter-date">${e(letterDate(s,n,ui))}${n.day<s.day?' · Kept correspondence':''}</p>`:''}${paragraphs(n.body)}${n.kind==='letter'&&n.personId?button('Find Their Recorded Place','notice-person',n.personId,'ghost small'):n.kind==='health'?button('Open Recovery','notice-recovery','','ghost small'):n.kind==='gift'?button('Open Inventory','notice-inventory','','ghost small'):''}</div>`:''}</article>`).join('')||'<div class="inbox-empty"><p>No letters or notices yet.</p><p class="muted">Letters, gifts and changes to your health will be kept here as they happen.</p></div>'}</div>`;
}
export function renderNotificationToasts(rows,ui,{hidden=false}={}){
  const {e}=ui;
  return `<aside class="notification-toast-stack" aria-label="New Notifications" aria-live="polite"${hidden?' inert aria-hidden="true"':''}>${rows.map(n=>`<article class="notification-toast"><button type="button" class="notification-toast-open" data-op="notification-toast-open" data-id="${e(n.id)}"><small>${names[n.kind]}</small><strong>${e(n.title)}</strong><span>${e(n.body.length>140?n.body.slice(0,137)+'…':n.body)}</span></button><button type="button" class="notification-dismiss" data-op="notice-dismiss" data-id="${e(n.id)}" aria-label="Dismiss ${e(n.title)}">×</button></article>`).join('')}</aside>`;
}
